1. verus! {
2. 
3. //==================================================================================================
4. // Transition lemmas for the kernel identity map
5. //
6. // Fully proven from the `IdentityMapView` spec definitions (no `admit()`). They expose the
7. // monotonicity / idempotence / accessibility facts of the View transitions
8. // (`spec_install_page`, `spec_map_page`) that the in-scope exec functions
9. // (`ensure_pte`, `identity_map_page`) rely on.
10. //==================================================================================================
11. 
12. // Installing a page makes that page a member of `mapped` (the V==P realization performed by
13. // `ensure_pte`).
14. pub proof fn lemma_install_page_maps(v: IdentityMapView, page: int)
15.     ensures
16.         v.spec_install_page(page).mapped.contains(page),
17. {
18.     assert(v.spec_install_page(page).mapped =~= v.mapped.insert(page));
19.     assert(v.mapped.insert(page).contains(page));
20. }
21. 
22. // Installing a page never removes an already-mapped page (monotonicity: once mapped, stays
23. // mapped).
24. pub proof fn lemma_install_page_monotone(v: IdentityMapView, page: int)
25.     ensures
26.         v.mapped.subset_of(v.spec_install_page(page).mapped),
27. {
28.     assert(v.spec_install_page(page).mapped =~= v.mapped.insert(page));
29.     assert forall|x: int| #[trigger] v.mapped.contains(x) implies
30.         v.mapped.insert(page).contains(x) by {}
31. }
32. 
33. // Installing a page preserves well-formedness when the new page is page-aligned and the mapper is
34. // initialized (`mapped` stays empty only before init).
35. pub proof fn lemma_install_page_preserves_inv(v: IdentityMapView, page: int)
36.     requires
37.         v.inv(),
38.         v.initialized,
39.         spec_is_page_aligned(page),
40.     ensures
41.         v.spec_install_page(page).inv(),
42. {
43.     let w = v.spec_install_page(page);
44.     assert(w.mapped =~= v.mapped.insert(page));
45.     assert(w.initialized == v.initialized);
46.     assert forall|p: int| #[trigger] w.mapped.contains(p) implies spec_is_page_aligned(p) by {
47.         assert(v.mapped.insert(page).contains(p));
48.         if p != page {
49.             assert(v.mapped.contains(p));
50.         }
51.     }
